# ==============================================================================
# Figure 2E: Structural remodeling among emerged-remodeling DETs
# ==============================================================================

counts_for_structure <- counts_filtered %>% dplyr::rename(tx_id = transcript_symbol)

count_long <- counts_for_structure %>%
  dplyr::select(tx_id, starts_with("C0_"), starts_with("C3_"), starts_with("C7_")) %>%
  pivot_longer(-tx_id, names_to = "sample", values_to = "count") %>%
  mutate(
    sample = standardize_sample_name(sample),
    condition = str_extract(sample, "^C\\d+")
  ) %>%
  left_join(counts_for_structure %>% distinct(tx_id, gene_symbol), by = "tx_id")

baseline_tbl_structure <- get_baseline_status(counts_for_structure, c0_cols, min_count, min_reps) %>%
  dplyr::select(tx_id, gene_symbol, n_C0_ge_min, iso_expressed_baseline, gene_has_any_baseline_isoform, baseline_status) %>%
  distinct(tx_id, .keep_all = TRUE)

c0_dominant_isoform <- count_long %>%
  filter(condition == "C0", !is.na(gene_symbol)) %>%
  group_by(gene_symbol, tx_id) %>%
  summarise(mean_count_C0 = mean(count, na.rm = TRUE), .groups = "drop") %>%
  left_join(
    baseline_tbl_structure %>% distinct(tx_id, gene_symbol, iso_expressed_baseline),
    by = c("tx_id", "gene_symbol")
  ) %>%
  filter(iso_expressed_baseline) %>%
  group_by(gene_symbol) %>%
  slice_max(mean_count_C0, n = 1, with_ties = FALSE) %>%
  ungroup() %>%
  dplyr::rename(ref_tx = tx_id)

tx_keep <- det_emerge_remodel %>%
  mutate(tx_id = transcript_symbol) %>%
  pull(tx_id) %>%
  union(c0_dominant_isoform$ref_tx) %>%
  unique() %>%
  na.omit()

known_tx_keep <- tx_keep[!str_detect(tx_keep, "novel")]
novel_tx_keep <- tx_keep[str_detect(tx_keep, "novel")]

# ---- Known transcript structure from Ensembl reference GTF --------------------
known_structure <- ref_gtf %>%
  mutate(transcript_name = if_else(is.na(transcript_name), transcript_id, transcript_name)) %>%
  filter(transcript_name %in% known_tx_keep, type %in% c("CDS", "five_prime_utr", "three_prime_utr")) %>%
  transmute(
    tx_id = transcript_name,
    gene_name,
    seqnames,
    start,
    end,
    strand,
    region_type = if_else(type == "CDS", "CDS", "UTR"),
    source = "Ensembl_reference",
    transcript_id
  ) %>%
  distinct()

# ---- Novel transcript ORF boundaries from SQANTI3 classifications -------------
orf_sqanti <- map_dfr(sqanti_class_files, ~ read_tsv(.x, show_col_types = FALSE)) %>%
  transmute(
    transcript_id,
    strand,
    coding,
    CDS_genomic_start_raw = suppressWarnings(as.numeric(CDS_genomic_start)),
    CDS_genomic_end_raw = suppressWarnings(as.numeric(CDS_genomic_end)),
    cds_len = abs(CDS_genomic_end_raw - CDS_genomic_start_raw)
  ) %>%
  group_by(transcript_id) %>%
  arrange(dplyr::desc(replace_na(cds_len, -Inf)), .by_group = TRUE) %>%
  dplyr::slice(1) %>%
  ungroup() %>%
  transmute(
    transcript_id,
    strand,
    coding,
    CDS_genomic_start = CDS_genomic_start_raw,
    CDS_genomic_end = CDS_genomic_end_raw
  ) %>%
  distinct()

# ---- Novel transcript exon and CDS coordinates from renamed GTF files ----------
gtf_all <- map_dfr(renamed_gtf_files, function(f) {
  rtracklayer::import(f) %>%
    as.data.frame() %>%
    filter(transcript_id %in% tx_keep) %>%
    mutate(sample = str_remove(basename(f), "\\.gtf$"))
})

cds_from_gtf <- gtf_all %>%
  filter(type == "CDS") %>%
  group_by(transcript_id) %>%
  summarise(
    CDS_genomic_start = min(start),
    CDS_genomic_end = max(end),
    .groups = "drop"
  )

orf_combined <- full_join(orf_sqanti, cds_from_gtf, by = "transcript_id") %>%
  transmute(
    transcript_id,
    coding,
    CDS_genomic_start = coalesce(CDS_genomic_start.x, CDS_genomic_start.y),
    CDS_genomic_end = coalesce(CDS_genomic_end.x, CDS_genomic_end.y)
  )

gtf_exons <- gtf_all %>%
  filter(type == "exon") %>%
  left_join(orf_combined, by = "transcript_id")

novel_selected <- gtf_exons %>%
  filter(transcript_id %in% novel_tx_keep) %>%
  arrange(transcript_id, start) %>%
  distinct(
    seqnames,
    start,
    end,
    strand,
    transcript_id,
    gene_id,
    coding,
    CDS_genomic_start,
    CDS_genomic_end,
    .keep_all = TRUE
  )

novel_structure <- novel_selected %>%
  rowwise() %>%
  do(split_exon_by_orf(.)) %>%
  ungroup() %>%
  mutate(
    tx_id = transcript_id,
    coding_class = coding,
    region_type = case_when(
      region_type == "CDS" ~ "CDS",
      region_type %in% c("5UTR", "3UTR", "UTR") ~ "UTR",
      TRUE ~ NA_character_
    ),
    source = "SQANTI3_ORF_prediction"
  ) %>%
  dplyr::select(tx_id, seqnames, start, end, strand, coding_class, region_type, source) %>%
  filter(!is.na(region_type)) %>%
  distinct()

tx_structure_all <- bind_rows(
  known_structure %>% dplyr::select(tx_id, seqnames, start, end, strand, region_type, source),
  novel_structure %>% dplyr::select(tx_id, seqnames, start, end, strand, region_type, source)
) %>%
  filter(!is.na(region_type)) %>%
  distinct()

isoform_structure_input <- det_emerge_remodel %>%
  mutate(tx_id = transcript_symbol) %>%
  left_join(
    baseline_tbl_structure %>% dplyr::select(tx_id, gene_symbol, iso_expressed_baseline, baseline_status),
    by = c("tx_id", "gene_symbol")
  ) %>%
  left_join(c0_dominant_isoform, by = "gene_symbol") %>%
  filter(!is.na(ref_tx), tx_id != ref_tx)

# Each DET is compared against the dominant baseline isoform of its gene.
compare_df <- isoform_structure_input %>%
  distinct(tx_id, ref_tx) %>%
  mutate(compare = map2(tx_id, ref_tx, ~ compare_tx_to_ref(.x, .y, tx_structure_all))) %>%
  dplyr::select(compare) %>%
  unnest(compare)

isoform_structure_gr <- isoform_structure_input %>%
  left_join(compare_df, by = c("tx_id", "ref_tx"))

# ---- Coding class annotation --------------------------------------------------
known_coding_by_cds <- ref_gtf %>%
  mutate(transcript_name = if_else(is.na(transcript_name), transcript_id, transcript_name)) %>%
  filter(transcript_name %in% known_tx_keep) %>%
  group_by(transcript_name) %>%
  summarise(
    has_CDS = any(type == "CDS"),
    transcript_biotype = dplyr::first(na.omit(transcript_biotype)),
    .groups = "drop"
  ) %>%
  mutate(
    tx_id = transcript_name,
    coding_class = if_else(has_CDS, "coding", "noncoding"),
    coding_source = "Ensembl_CDS_presence"
  ) %>%
  dplyr::select(tx_id, coding_class, coding_source, transcript_biotype, has_CDS)

novel_biotype <- orf_combined %>%
  filter(transcript_id %in% novel_tx_keep) %>%
  mutate(
    tx_id = transcript_id,
    has_predicted_orf = !is.na(CDS_genomic_start) & !is.na(CDS_genomic_end),
    coding_class = if_else(coding == "coding", "coding", "noncoding"),
    coding_source = "SQANTI3_ORF_prediction",
    transcript_biotype = if_else(has_predicted_orf, "predicted_protein_coding", "predicted_noncoding")
  ) %>%
  dplyr::select(tx_id, coding_class, coding_source, transcript_biotype)

tx_coding_annot <- bind_rows(known_coding_by_cds, novel_biotype) %>%
  distinct(tx_id, .keep_all = TRUE)

isoform_structure_gr <- isoform_structure_gr %>%
  left_join(
    tx_coding_annot %>%
      dplyr::rename(
        tx_coding_class = coding_class,
        tx_coding_source = coding_source,
        tx_biotype = transcript_biotype
      ),
    by = "tx_id"
  ) %>%
  left_join(
    tx_coding_annot %>%
      dplyr::rename(
        ref_tx = tx_id,
        ref_coding_class = coding_class,
        ref_coding_source = coding_source,
        ref_biotype = transcript_biotype
      ),
    by = "ref_tx"
  ) %>%
  mutate(
    coding_transition = case_when(
      ref_coding_class == "coding" & tx_coding_class == "coding" ~ "coding_to_coding",
      ref_coding_class == "coding" & tx_coding_class == "noncoding" ~ "coding_to_noncoding",
      ref_coding_class == "noncoding" & tx_coding_class == "coding" ~ "noncoding_to_coding",
      ref_coding_class == "noncoding" & tx_coding_class == "noncoding" ~ "noncoding_to_noncoding",
      TRUE ~ "unknown"
    ),
    comparison_type = case_when(
      !str_detect(tx_id, "novel") & !str_detect(ref_tx, "novel") ~ "known_vs_known",
      str_detect(tx_id, "novel") & !str_detect(ref_tx, "novel") ~ "novel_vs_known",
      !str_detect(tx_id, "novel") & str_detect(ref_tx, "novel") ~ "known_vs_novel",
      str_detect(tx_id, "novel") & str_detect(ref_tx, "novel") ~ "novel_vs_novel",
      TRUE ~ "unknown"
    ),
    final_class = case_when(
      structure_change_class == "UTR only" ~ "UTR Only",
      str_starts(structure_change_class, "CDS") ~ "ORF Modification",
      structure_change_class == "Coding-Noncoding Switch" & coding_transition == "noncoding_to_coding" ~ "ORF Gain",
      structure_change_class == "Coding-Noncoding Switch" & coding_transition == "coding_to_noncoding" ~ "ORF Loss",
      structure_change_class == "Coding-Noncoding Switch" & coding_transition == "noncoding_to_noncoding" ~ "Noncoding",
      TRUE ~ "unknown"
    )
  )

write_csv(isoform_structure_gr, file.path(results_dir, "Fig2E_isoform_structure_comparison_source_data.csv"))

remodel_plot_df <- isoform_structure_gr %>%
  filter(final_class %in% remodel_class_levels) %>%
  dplyr::count(contrast_pretty, final_class, name = "n_isoforms") %>%
  complete(
    contrast_pretty = comparison_levels,
    final_class = remodel_class_levels,
    fill = list(n_isoforms = 0)
  ) %>%
  group_by(contrast_pretty) %>%
  mutate(value = 100 * n_isoforms / sum(n_isoforms)) %>%
  ungroup() %>%
  mutate(
    contrast_pretty = factor(contrast_pretty, levels = comparison_levels),
    final_class = factor(final_class, levels = remodel_class_levels)
  )

p_remodeling <- ggplot(remodel_plot_df, aes(x = contrast_pretty, y = value, fill = final_class)) +
  geom_col(width = 0.9, color = "black", linewidth = 0.25) +
  geom_text(aes(label = pct_lab_value(value)), position = position_stack(vjust = 0.5), size = 1.6) +
  scale_y_continuous(expand = c(0, 0), labels = function(x) paste0(x, "%"), position = "right") +
  coord_cartesian(ylim = c(0, 100)) +
  scale_fill_discrete(palette = "Set2", labels = function(x) str_wrap(x, width = 18)) +
  labs(x = NULL, y = NULL, title = "Remodeling of DETs", fill = NULL) +
  theme_pub() +
  theme(
    legend.position = "bottom",
    legend.box = "horizontal",
    legend.key.size = unit(2, "mm"),
    legend.text = element_text(size = 5),
    legend.spacing.y = unit(1, "mm"),
    legend.spacing.x = unit(1, "mm"),
    legend.box.margin = margin(t = -2, r = -4, b = 0, l = 0, unit = "mm")
  ) +
  guides(fill = guide_legend(nrow = 2, byrow = FALSE))

save_panel(p_remodeling, "Fig2E_UTR_CDS_ORF_Remodeling.png", width_mm = 50, height_mm = 68)
